import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeft, Camera, FileCheck, AlertCircle, BookOpen, ShieldCheck,
  Sparkles, Tag, Hash, Layers, FileText, Zap,
} from "lucide-react";
import { Card, PageHeader, Button, CountUp } from "@/components/ui";
import { getTemplate } from "@/mock";
import type { PhotoCategory } from "@/types";
import { cn } from "@/lib/utils";

// 分类对应的 emoji
const CATEGORY_EMOJI: Record<PhotoCategory, string> = {
  "食材标签": "🍼",
  "冰箱温度": "🧊",
  "操作台": "🧹",
  "台账记录": "📋",
  "垃圾桶": "🗑️",
  "消毒柜": "🔧",
  "仓储": "📦",
  "洗手池": "🧼",
  "健康证": "👤",
};

const TYPE_HERO: Record<string, {
  badge: string;
  gradient: string;
  shadow: string;
  shortLabel: string;
}> = {
  daily: {
    badge: "bg-emerald-50 text-emerald-700 border-emerald-200",
    gradient: "from-emerald-500 to-cyan-500",
    shadow: "shadow-[0_0_20px_rgba(16,185,129,0.4)]",
    shortLabel: "DAILY",
  },
  standard: {
    badge: "bg-brand-50 text-brand-700 border-brand-200",
    gradient: "from-brand-900 to-cyan-600",
    shadow: "shadow-glow-brand",
    shortLabel: "STANDARD",
  },
  special: {
    badge: "bg-red-50 text-red-700 border-red-200",
    gradient: "from-red-500 to-orange-500",
    shadow: "shadow-[0_0_20px_rgba(220,38,38,0.4)]",
    shortLabel: "SPECIAL",
  },
};

export default function TemplateDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const tpl = getTemplate(id || "");

  // 模板不存在
  if (!tpl) {
    return (
      <div className="animate-fade-in flex flex-col items-center justify-center min-h-[50vh] text-center">
        <div className="w-16 h-16 rounded-2xl bg-ink-100 flex items-center justify-center mb-4">
          <AlertCircle className="w-8 h-8 text-ink-400" />
        </div>
        <h2 className="text-xl font-bold text-ink-800 mb-2">模板不存在</h2>
        <p className="text-sm text-ink-500 mb-6">该模板 ID 可能已被删除或地址输入有误</p>
        <Button variant="gradient" onClick={() => navigate("/template")}>
          <ArrowLeft className="w-4 h-4" /> 返回模板列表
        </Button>
      </div>
    );
  }

  const hero = TYPE_HERO[tpl.type] ?? TYPE_HERO.standard;

  // 统计
  const photoCount = tpl.items.reduce(
    (s, it) => s + (it.photoReq.includes("≥") ? 2 : 1),
    0
  );
  const highRiskItems = tpl.items.filter((it) => it.riskRule.includes("高风险")).length;

  return (
    <div className="animate-fade-in">
      <PageHeader
        title={tpl.name}
        subtitle="模板详情 · 检查项配置"
        badge={
          <span className={cn(
            "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-semibold tracking-wider border",
            hero.badge
          )}>
            <Sparkles className="w-3 h-3" /> {hero.shortLabel}
          </span>
        }
        actions={
          <>
            <Button
              variant="gradient"
              size="md"
              onClick={() => navigate(`/inspection/new?templateId=${tpl.id}`)}
              icon={<Zap className="w-4 h-4" />}
            >
              使用此模板巡检
            </Button>
            <Button
              variant="secondary"
              size="md"
              onClick={() => navigate("/template")}
              icon={<ArrowLeft className="w-4 h-4" />}
            >
              返回列表
            </Button>
          </>
        }
      />

      {/* Hero 卡片 */}
      <div className={cn(
        "relative rounded-2xl bg-gradient-to-r p-6 text-white overflow-hidden mb-6",
        hero.gradient
      )}>
        <div className="absolute -top-20 -right-10 w-72 h-72 rounded-full bg-cyan-500/20 blur-3xl pointer-events-none" />
        <div className="absolute -bottom-16 -left-10 w-64 h-64 rounded-full bg-white/10 blur-2xl pointer-events-none" />

        <div className="relative grid grid-cols-[1fr_auto] gap-6 items-center">
          <div>
            <div className="flex items-center gap-3 mb-3">
              <span className={cn(
                "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold tracking-wider bg-white/20 backdrop-blur border border-white/30"
              )}>
                <Sparkles className="w-3 h-3" /> {hero.shortLabel}
              </span>
              <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-semibold tracking-wider bg-white/15 backdrop-blur border border-white/20">
                {tpl.typeName}
              </span>
            </div>
            <h1 className="text-3xl font-bold font-display tracking-tight mb-2">
              {tpl.name}
            </h1>
            <p className="text-sm text-white/80 leading-relaxed max-w-2xl">
              {tpl.description}
            </p>
          </div>

          <div className={cn(
            "w-24 h-24 rounded-2xl bg-white/15 backdrop-blur border border-white/30 flex items-center justify-center text-4xl",
            hero.shadow
          )}>
            📋
          </div>
        </div>

        {/* Hero 统计 */}
        <div className="relative grid grid-cols-4 gap-4 mt-6 pt-6 border-t border-white/20">
          <div>
            <p className="text-[10px] text-white/70 font-semibold tracking-widest uppercase mb-1">
              检查项
            </p>
            <p className="text-3xl font-bold font-display tracking-tight tabular-nums">
              <CountUp end={tpl.itemCount} duration={1200} />
            </p>
          </div>
          <div>
            <p className="text-[10px] text-white/70 font-semibold tracking-widest uppercase mb-1">
              拍照要求
            </p>
            <p className="text-3xl font-bold font-display tracking-tight tabular-nums">
              <CountUp end={photoCount} duration={1200} suffix=" 张" />
            </p>
          </div>
          <div>
            <p className="text-[10px] text-white/70 font-semibold tracking-widest uppercase mb-1">
              高风险规则
            </p>
            <p className="text-3xl font-bold font-display tracking-tight tabular-nums">
              <CountUp end={highRiskItems} duration={1200} />
            </p>
          </div>
          <div>
            <p className="text-[10px] text-white/70 font-semibold tracking-widest uppercase mb-1">
              适用范围
            </p>
            <p className="text-lg font-bold font-display tracking-tight leading-tight pt-2">
              {tpl.typeName.split(/[·•·]/)[0] || "全场景"}
            </p>
          </div>
        </div>
      </div>

      {/* 元信息条 */}
      <div className="grid grid-cols-3 gap-3 mb-5">
        <Card className="p-3 flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-brand-50 flex items-center justify-center">
            <Hash className="w-4 h-4 text-brand-700" />
          </div>
          <div className="min-w-0">
            <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">模板编号</p>
            <p className="text-sm font-mono text-ink-800 truncate">{tpl.id}</p>
          </div>
        </Card>
        <Card className="p-3 flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-cyan-50 flex items-center justify-center">
            <Tag className="w-4 h-4 text-cyan-700" />
          </div>
          <div className="min-w-0">
            <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">模板类型</p>
            <p className="text-sm text-ink-800 truncate">{tpl.typeName}</p>
          </div>
        </Card>
        <Card className="p-3 flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-violet-50 flex items-center justify-center">
            <Layers className="w-4 h-4 text-violet-700" />
          </div>
          <div className="min-w-0">
            <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">检查分类</p>
            <p className="text-sm text-ink-800 truncate">
              {new Set(tpl.items.map((it) => it.category)).size} 大类
            </p>
          </div>
        </Card>
      </div>

      {/* 检查项列表标题 */}
      <div className="mb-4 flex items-end justify-between">
        <div>
          <p className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase">Item Details</p>
          <h3 className="text-base font-bold font-display tracking-tight text-ink-900 mt-0.5">
            检查项详情
            <span className="text-ink-400 text-sm font-normal ml-2">共 {tpl.items.length} 项</span>
          </h3>
        </div>
        <Button variant="ghost" size="sm" icon={<FileText className="w-3.5 h-3.5" />}>
          查看法规全文
        </Button>
      </div>

      {/* 检查项 */}
      <div className="space-y-3">
        {tpl.items.map((item, i) => (
          <Card
            key={i}
            className="group p-5 hover:shadow-elevated transition-all duration-300 hover:border-brand-300"
          >
            {/* 头部 */}
            <div className="flex items-start gap-3 mb-4">
              <div className="flex-shrink-0 w-9 h-9 rounded-lg bg-gradient-to-br from-brand-900 to-cyan-600 text-white text-xs font-bold flex items-center justify-center shadow-glow-brand tabular-nums">
                {String(i + 1).padStart(2, "0")}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap mb-1">
                  <h4 className="text-base font-bold font-display tracking-tight text-ink-900">
                    {item.name}
                  </h4>
                  <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] bg-ink-100/80 text-ink-600 font-medium border border-ink-200/60">
                    <span>{CATEGORY_EMOJI[item.category]}</span>
                    {item.category}
                  </span>
                </div>
              </div>
            </div>

            {/* 详细字段 2x2 */}
            <div className="grid grid-cols-2 gap-3">
              {/* 检查标准 */}
              <div className="rounded-lg bg-emerald-50/50 border border-emerald-100/80 p-3">
                <div className="flex items-center gap-1.5 mb-1.5">
                  <div className="w-5 h-5 rounded-md bg-emerald-100 flex items-center justify-center">
                    <FileCheck className="w-3 h-3 text-emerald-600" />
                  </div>
                  <p className="text-[10px] text-emerald-700 font-semibold tracking-widest uppercase">
                    检查标准
                  </p>
                </div>
                <p className="text-xs text-ink-700 leading-relaxed">{item.standard}</p>
              </div>

              {/* 拍照要求 */}
              <div className="rounded-lg bg-cyan-50/50 border border-cyan-100/80 p-3">
                <div className="flex items-center gap-1.5 mb-1.5">
                  <div className="w-5 h-5 rounded-md bg-cyan-100 flex items-center justify-center">
                    <Camera className="w-3 h-3 text-cyan-600" />
                  </div>
                  <p className="text-[10px] text-cyan-700 font-semibold tracking-widest uppercase">
                    拍照要求
                  </p>
                </div>
                <p className="text-xs text-ink-700 leading-relaxed">{item.photoReq}</p>
              </div>

              {/* 风险判定 */}
              <div className="rounded-lg bg-orange-50/50 border border-orange-100/80 p-3">
                <div className="flex items-center gap-1.5 mb-1.5">
                  <div className="w-5 h-5 rounded-md bg-orange-100 flex items-center justify-center">
                    <AlertCircle className="w-3 h-3 text-orange-600" />
                  </div>
                  <p className="text-[10px] text-orange-700 font-semibold tracking-widest uppercase">
                    风险判定规则
                  </p>
                </div>
                <p className="text-xs text-ink-700 leading-relaxed">{item.riskRule}</p>
              </div>

              {/* 法规依据 */}
              <div className="rounded-lg bg-violet-50/50 border border-violet-100/80 p-3">
                <div className="flex items-center gap-1.5 mb-1.5">
                  <div className="w-5 h-5 rounded-md bg-violet-100 flex items-center justify-center">
                    <BookOpen className="w-3 h-3 text-violet-600" />
                  </div>
                  <p className="text-[10px] text-violet-700 font-semibold tracking-widest uppercase">
                    法规依据
                  </p>
                </div>
                <p className="text-xs text-ink-700 leading-relaxed">{item.regulation}</p>
              </div>
            </div>

            {/* 底部小提示 */}
            <div className="flex items-center gap-1.5 mt-3 pt-3 border-t border-dashed border-ink-100">
              <ShieldCheck className="w-3.5 h-3.5 text-emerald-500" />
              <p className="text-[11px] text-ink-400">
                AI 识别将自动匹配此规则，请确保拍照清晰合规
              </p>
            </div>
          </Card>
        ))}
      </div>

      {/* 底部返回 */}
      <div className="flex justify-center mt-8">
        <Button
          variant="secondary"
          size="md"
          onClick={() => navigate("/template")}
          icon={<ArrowLeft className="w-4 h-4" />}
        >
          返回模板列表
        </Button>
      </div>
    </div>
  );
}
